const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

// 1. Extract Token from Authorization header (Bearer <token>) or body/query
let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Please log in again."
    }
  }];
}

const callerId = String(claims.sub).trim();
const callerRole = String(claims.role || 'EMPLOYEE').toUpperCase().trim();

const webhookNode = $('Webhook - POST /salary-deductions').first().json || {};
const body = webhookNode.body || {};

let targetEmployeeId = callerId;
if (callerRole === 'ADMIN' && body.employeeId) {
  targetEmployeeId = String(body.employeeId).trim();
}

let targetMonth = String(body.month || '').trim();
if (!targetMonth || !/^\d{4}-\d{2}$/.test(targetMonth)) {
  const now = new Date();
  targetMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
}

return [{
  json: {
    valid: true,
    callerId: callerId,
    callerRole: callerRole,
    targetEmployeeId: targetEmployeeId,
    targetMonth: targetMonth
  }
}];

const inputRow = $input.first().json || {};
const emp = inputRow.employee || {};

if (!emp.id) {
  return [{
    json: {
      valid: false,
      statusCode: 404,
      error: "Employee record not found in database."
    }
  }];
}

const targetInfo = $('Code - Process Claims & Target Employee').first().json || {};
const webhookBody = $('Webhook - POST /salary-deductions').first().json.body || {};

// Salary is ALWAYS read from DB - never modified by this workflow
const salary = parseFloat(emp.salary || '0');
const monthKey = targetInfo.targetMonth;
const [yStr, mStr] = monthKey.split('-');
const year = parseInt(yStr, 10);
const month = parseInt(mStr, 10);

// 1. Total calendar days in the month
const daysInMonth = new Date(year, month, 0).getDate();

// 2. Exact user calculation rules:
// dailySalary = floor(salary / daysInMonth)
const dailySalary = Math.floor(salary / daysInMonth);
// halfDaySalary = floor(dailySalary / 2)
const halfDaySalary = Math.floor(dailySalary / 2);
// full day leave deduction rate = 2 * halfDaySalary
const fullDayDeductionRate = 2 * halfDaySalary;

// 3. Holidays mapping
const holidaysMap = {};
for (const h of (inputRow.holidays || [])) {
  holidaysMap[h.date] = h;
}

// 4. Attendances mapping
const attendancesMap = {};
for (const a of (inputRow.attendances || [])) {
  attendancesMap[a.date] = a;
}

// 5. Existing adjustment leave requests mapping (so we NEVER double deduct!)
const existingAdjustments = {};
for (const r of (inputRow.leave_requests || [])) {
  if (r.id && r.id.startsWith('lev-adj-')) {
    existingAdjustments[r.id] = r;
  }
}

// 6. Initial Leave balances tracking
const leaveBalances = Array.isArray(inputRow.leave_balances) ? inputRow.leave_balances : [];
const initialBalances = {
  HALF_DAY: 6.0,
  CASUAL: 12.0,
  SICK: 12.0,
  EARNED: 15.0
};
const liveBalances = {
  HALF_DAY: 6.0,
  CASUAL: 12.0,
  SICK: 12.0,
  EARNED: 15.0
};

for (const b of leaveBalances) {
  const avail = parseFloat(b.available || '0');
  initialBalances[b.type] = avail;
  liveBalances[b.type] = avail;
}

const incidents = [];
let halfDaysAdjustedCount = 0;
let halfDaysDeductedCount = 0;
let fullDaysAdjustedCount = 0;
let fullDaysDeductedCount = 0;
let totalDeductionAmount = 0;
let totalWorkingDays = 0;

const sqlStatements = [];

// employees.salary is READ-ONLY - never updated by this workflow

// 7. Scan month calendar chronologically
for (let day = 1; day <= daysInMonth; day++) {
  const dayStr = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  const dateObj = new Date(year, month - 1, day);
  const dayOfWeek = dateObj.getDay();

  const isSunday = (dayOfWeek === 0);
  const isHoliday = !!holidaysMap[dayStr];

  if (!isSunday && !isHoliday) {
    totalWorkingDays++;
  }

  const att = attendancesMap[dayStr];
  if (att) {
    const adjLeaveId = `lev-adj-${att.id}`;
    const notifId = `notif-adj-${att.id}`;
    const alreadyAdjustedInDb = !!existingAdjustments[adjLeaveId];

    // Case A: Half-day penalty (late past 10:45 AM cutoff or exceeded 3 monthly allowances)
    if (att.is_half_day_case === true || att.status === 'HALF_DAY') {
      const checkInTime = att.check_in || 'Late Punch';

      if (alreadyAdjustedInDb) {
        // Already recorded & deducted in database previously
        halfDaysAdjustedCount++;
        const prevReq = existingAdjustments[adjLeaveId];
        const adjType = prevReq.leave_type || 'HALF_DAY';
        incidents.push({
          id: `inc-${dayStr}-half`,
          date: dayStr,
          incidentType: 'LATE_PAST_CUTOFF',
          title: `Late Arrival: ${checkInTime}`,
          type: 'HALF_DAY',
          penaltyUnits: 0.5,
          status: 'ADJUSTED_WITH_LEAVE',
          adjustedLeaveType: adjType,
          leaveDaysDeducted: 0.5,
          deductionAmount: 0,
          description: `Adjusted against ${adjType} Leave balance in database. No salary deducted.`,
          checkInTime: att.check_in
        });
      } else {
        // Priority 1: Check HALF_DAY leave balance
        if (liveBalances['HALF_DAY'] >= 0.5) {
          liveBalances['HALF_DAY'] -= 0.5;
          halfDaysAdjustedCount++;

          // Generate DB Update Statements
          sqlStatements.push(`
            UPDATE leave_balances
            SET used = used + 0.5
            WHERE employee_id = '${emp.id}'
              AND leave_type = 'HALF_DAY'
              AND year = ${year};

            INSERT INTO leave_requests (
              id, employee_id, leave_type, duration_type,
              start_date, end_date, days_count, reason,
              status, applied_on, approved_or_rejected_by,
              reviewed_on, comments, whatsapp_notice_acknowledged
            ) VALUES (
              '${adjLeaveId}',
              '${emp.id}',
              'HALF_DAY',
              'FIRST_HALF',
              '${dayStr}'::DATE,
              '${dayStr}'::DATE,
              0.5,
              'Auto-adjustment for late arrival past cutoff (0.5 day)',
              'APPROVED',
              CURRENT_DATE,
              'SYSTEM_SALARY_PROTECTION',
              CURRENT_DATE,
              'Auto-adjusted from Half-Day Leave balance to protect monthly salary from deductions.',
              TRUE
            ) ON CONFLICT (id) DO NOTHING;

            UPDATE attendances
            SET 
              notes = 'LEAVE_ADJUSTED:HALF_DAY:0.5',
              status_label = 'Half Day (Leave Protected)'
            WHERE id = '${att.id}';

            INSERT INTO notifications (
              id, employee_id, category, title, message, action_route, priority, is_read
            ) VALUES (
              '${notifId}',
              '${emp.id}',
              'LEAVE_UPDATE',
              'Salary Protected by Leave Balance',
              'Your late arrival on ${dayStr} was automatically adjusted against 0.5 Half-Day Leave. Zero salary deducted.',
              '/salary',
              'NORMAL',
              FALSE
            ) ON CONFLICT (id) DO NOTHING;
          `);

          incidents.push({
            id: `inc-${dayStr}-half`,
            date: dayStr,
            incidentType: 'LATE_PAST_CUTOFF',
            title: `Late Arrival: ${checkInTime}`,
            type: 'HALF_DAY',
            penaltyUnits: 0.5,
            status: 'ADJUSTED_WITH_LEAVE',
            adjustedLeaveType: 'HALF_DAY',
            leaveDaysDeducted: 0.5,
            deductionAmount: 0,
            description: `Adjusted against available Half-Day Leave (0.5 day). Remaining Half-Day balance: ${liveBalances['HALF_DAY']}. Database updated. No salary deducted.`,
            checkInTime: att.check_in
          });
        } else if (liveBalances['CASUAL'] >= 0.5) {
          // Priority 2: Check CASUAL leave balance
          liveBalances['CASUAL'] -= 0.5;
          halfDaysAdjustedCount++;

          sqlStatements.push(`
            UPDATE leave_balances
            SET used = used + 0.5
            WHERE employee_id = '${emp.id}'
              AND leave_type = 'CASUAL'
              AND year = ${year};

            INSERT INTO leave_requests (
              id, employee_id, leave_type, duration_type,
              start_date, end_date, days_count, reason,
              status, applied_on, approved_or_rejected_by,
              reviewed_on, comments, whatsapp_notice_acknowledged
            ) VALUES (
              '${adjLeaveId}',
              '${emp.id}',
              'CASUAL',
              'FIRST_HALF',
              '${dayStr}'::DATE,
              '${dayStr}'::DATE,
              0.5,
              'Auto-adjustment for late arrival past cutoff (0.5 day Casual Leave)',
              'APPROVED',
              CURRENT_DATE,
              'SYSTEM_SALARY_PROTECTION',
              CURRENT_DATE,
              'Half-Day balance was 0. Auto-adjusted from Casual Leave balance to protect monthly salary.',
              TRUE
            ) ON CONFLICT (id) DO NOTHING;

            UPDATE attendances
            SET 
              notes = 'LEAVE_ADJUSTED:CASUAL:0.5',
              status_label = 'Half Day (Casual Leave Protected)'
            WHERE id = '${att.id}';

            INSERT INTO notifications (
              id, employee_id, category, title, message, action_route, priority, is_read
            ) VALUES (
              '${notifId}',
              '${emp.id}',
              'LEAVE_UPDATE',
              'Salary Protected by Casual Leave',
              'Your late arrival on ${dayStr} was automatically adjusted against 0.5 Casual Leave. Zero salary deducted.',
              '/salary',
              'NORMAL',
              FALSE
            ) ON CONFLICT (id) DO NOTHING;
          `);

          incidents.push({
            id: `inc-${dayStr}-half`,
            date: dayStr,
            incidentType: 'LATE_PAST_CUTOFF',
            title: `Late Arrival: ${checkInTime}`,
            type: 'HALF_DAY',
            penaltyUnits: 0.5,
            status: 'ADJUSTED_WITH_LEAVE',
            adjustedLeaveType: 'CASUAL',
            leaveDaysDeducted: 0.5,
            deductionAmount: 0,
            description: `Half-Day balance was 0. Adjusted against Casual Leave (0.5 day). Remaining Casual balance: ${liveBalances['CASUAL']}. Database updated. No salary deducted.`,
            checkInTime: att.check_in
          });
        } else {
          // Priority 3: Leaves exhausted (0 balance) -> Deduct half-day salary
          halfDaysDeductedCount++;
          totalDeductionAmount += halfDaySalary;

          sqlStatements.push(`
            UPDATE attendances
            SET 
              notes = 'SALARY_DEDUCTED:HALF_DAY:${halfDaySalary}',
              status_label = 'Half Day (Salary Deducted)'
            WHERE id = '${att.id}';
          `);

          incidents.push({
            id: `inc-${dayStr}-half`,
            date: dayStr,
            incidentType: 'LATE_PAST_CUTOFF',
            title: `Late Arrival: ${checkInTime}`,
            type: 'HALF_DAY',
            penaltyUnits: 0.5,
            status: 'SALARY_DEDUCTED',
            adjustedLeaveType: null,
            leaveDaysDeducted: 0,
            deductionAmount: halfDaySalary,
            description: `All eligible leave balances exhausted (0 remaining). Deducted half-day salary: ₹${halfDaySalary}.`,
            checkInTime: att.check_in
          });
        }
      }
    }
  }
}

const projectedNetSalary = Math.max(0, salary - totalDeductionAmount);
const monthNames = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];
const monthName = `${monthNames[month - 1]} ${year}`;

const balanceSummary = [
  {
    type: 'HALF_DAY',
    label: 'Half-Day Leave',
    initialAvailable: initialBalances['HALF_DAY'],
    usedForSalaryAdjustment: initialBalances['HALF_DAY'] - liveBalances['HALF_DAY'],
    currentAvailable: liveBalances['HALF_DAY']
  },
  {
    type: 'CASUAL',
    label: 'Casual Leave',
    initialAvailable: initialBalances['CASUAL'],
    usedForSalaryAdjustment: initialBalances['CASUAL'] - liveBalances['CASUAL'],
    currentAvailable: liveBalances['CASUAL']
  },
  {
    type: 'SICK',
    label: 'Sick Leave',
    initialAvailable: initialBalances['SICK'],
    usedForSalaryAdjustment: 0,
    currentAvailable: liveBalances['SICK']
  },
  {
    type: 'EARNED',
    label: 'Earned Leave',
    initialAvailable: initialBalances['EARNED'],
    usedForSalaryAdjustment: 0,
    currentAvailable: liveBalances['EARNED']
  }
];

const hasUpdates = sqlStatements.length > 0;
const combinedSql = sqlStatements.join('\n');

return [{
  json: {
    valid: true,
    hasUpdates: hasUpdates,
    sqlUpdates: combinedSql,
    breakdown: {
      monthKey: monthKey,
      monthName: monthName,
      daysInMonth: daysInMonth,
      monthlySalary: salary,
      dailySalary: dailySalary,
      halfDaySalary: halfDaySalary,
      fullDayDeductionRate: fullDayDeductionRate,
      totalDeductionAmount: totalDeductionAmount,
      projectedNetSalary: projectedNetSalary,
      totalWorkingDays: totalWorkingDays,
      totalIncidents: incidents.length,
      halfDaysAdjustedCount: halfDaysAdjustedCount,
      halfDaysDeductedCount: halfDaysDeductedCount,
      fullDaysAdjustedCount: fullDaysAdjustedCount,
      fullDaysDeductedCount: fullDaysDeductedCount,
      totalLeaveDaysConsumed: (halfDaysAdjustedCount * 0.5) + fullDaysAdjustedCount,
      incidents: incidents,
      leaveBalances: balanceSummary
    }
  }
}];

const prev = $('Code - Compute Adjustments & Prepare DB Updates').first().json || {};

return [{
  json: {
    success: true,
    statusCode: 200,
    breakdown: prev.breakdown
  }
}];

